import {icon,avatar,person,avatarGroup,cover,productPhoto} from './visuals.js';

// Each home screen has its own composition. Actions use the same application
// state and routes as their detail pages, rather than separate decorative data.
export function workspaceHome({state,teams,head,link,url,esc,btn}) {
 const progress=state.teams.length?Math.round(state.teams.reduce((n,t)=>n+t.progress,0)/state.teams.length):0;
 return head('Team workspace','Monday, 2 November · Your workspace at a glance',btn('New team','new-team'))+`
 <section class="workspace-lead"><div class="workspace-story"><span class="eyebrow">NORTHSTAR / WEEK 45</span><h2>A shared space.<br>A clear direction.</h2><p>${state.teams.length} teams moving toward the next milestone. Start with the people and projects that need you.</p><div class="app-actions">${link('Browse teams',url('teams'),true)}${link('Your people →',url('members'))}</div><div class="workspace-pulse">${avatarGroup(state.members.map(m=>m.name),state.members.length)}<span>${state.members.length} people in your directory</span></div></div><img class="workspace-photo" src="assets/studio-office.jpg" alt="Bright collaborative studio with long shared work tables" width="1400" height="933"><div class="workspace-score"><span>Sprint completion</span><strong>${progress}%</strong><progress max="100" value="${progress}" aria-label="Average sprint completion"></progress></div></section>
 <div class="workspace-board"><section><header class="section-title"><div><span class="eyebrow">IN MOTION</span><h2>Your teams</h2></div>${link('All teams →',url('teams'))}</header><div class="project-grid">${teams.map((t,i)=>`<article class="project-card">${cover(state.teams.indexOf(t),t.name)}<div class="project-body"><span class="project-symbol">${icon(['design','code','growth'][i%3])}</span><h3>${link(t.name,url('teams',{id:t.id}))}</h3><p>${esc(t.description)}</p><div class="project-progress"><span>Sprint progress</span><strong>${t.progress}%</strong></div><progress class="app-progress" max="100" value="${t.progress}" aria-label="${esc(t.name)} completion"></progress><footer>${person(t.lead,'Team lead')}${avatarGroup(undefined,t.members)}</footer></div></article>`).join('')||'<p>No teams match your search.</p>'}</div></section>
 <aside class="workspace-day"><span class="eyebrow">YOUR MONDAY</span><h2>Let’s get aligned.</h2><div class="calendar-strip" aria-label="Week starting November 2"><span data-today>MON<b>02</b></span><span>TUE<b>03</b></span><span>WED<b>04</b></span><span>THU<b>05</b></span><span>FRI<b>06</b></span></div><div class="agenda-item"><time>09:00<br>09:30</time><div><h3>Weekly planning</h3><p>Team room · ${state.agenda.filter(Boolean).length}/3 items complete</p>${avatarGroup()}<p>${link('Open meeting agenda →',url('agenda'))}</p></div></div><h3>Latest updates</h3><ul class="workspace-updates">${state.activity.slice(0,3).map(t=>`<li>${icon('resolved')}<span>${esc(t)}</span></li>`).join('')}</ul>${link('View activity →',url('activity'))}</aside></div>`;
}

export function accountHome({state,head,link,url,esc,match}) {
 const sections=[['profile','Personal information','Your name, email and company',state.profile.company],['security','Sign-in & devices','Review access and security preferences',state.sessions.length+' active sessions'],['billing','Subscription & invoices','Plan details and downloadable receipts',state.plan+' plan'],['members','People & permissions','Manage members and their workspace roles',state.members.length+' members']];
 return head('Account overview','Profile, security and workspace access.',link('Edit profile',url('profile'),true))+`
 <section class="account-cover"><img src="assets/meeting-space.jpg" alt="Sunlit studio meeting room" width="1400" height="933"><span>FORMA STUDIO <span>/ MEMBER SPACE</span></span></section>
 <div class="account-desk"><aside class="identity-card">${avatar(state.profile.name,true)}<span class="eyebrow">WORKSPACE OWNER</span><h2>${esc(state.profile.name)}</h2><p>${esc(state.profile.email)}</p><div class="identity-company">${icon('teams')}<strong>${esc(state.profile.company)}</strong></div><dl><div><dt>Plan</dt><dd>${esc(state.plan)}</dd></div><div><dt>Members</dt><dd>${state.members.length}</dd></div><div><dt>Demo sessions</dt><dd>${state.sessions.length}</dd></div></dl>${link('Manage your profile →',url('profile'))}</aside>
 <section class="account-directory"><header class="section-title"><div><span class="eyebrow">ACCOUNT SETTINGS</span><h2>Everything under your control</h2></div>${icon('security')}</header>${sections.filter(x=>match(x.join(' '))).map(([v,title,description,value])=>`<a class="settings-row" href="${url(v)}"><span class="settings-icon">${icon(v)}</span><span><strong>${title}</strong><small>${description}</small></span><span class="settings-value">${esc(value)}</span>${icon('arrow')}</a>`).join('')||'<p>No settings match your search.</p>'}<div class="account-bottom"><section class="security-summary">${icon('security')}<h3>Security check</h3><p>${state.security.twoFactor?'Two-step verification is enabled in this demo.':'Two-step verification is off in this demo.'}</p>${link('Review security →',url('security'))}</section><section><span class="eyebrow">YOUR WORKSPACE</span><h3>Good work takes a team.</h3>${avatarGroup(state.members.map(m=>m.name),state.members.length)}<p>${link('Manage people and roles →',url('members'))}</p></section></div></section></div>`;
}

export function commerceHome({state,head,link,url,money,orders,btn}) {
 const revenue=state.orders.filter(o=>o.status!=='Cancelled').reduce((n,o)=>n+o.total,0),processing=state.orders.filter(o=>o.status==='Processing'),low=state.products.filter(p=>p.stock<10);
 return head('Store overview','Fieldwork / Goods for everyday living',link('Manage orders',url('orders'),true))+`
 <div class="store-layout"><section class="store-main"><div class="collection-heading"><div><span class="eyebrow">THE FIELDWORK COLLECTION</span><h2>Objects with purpose.</h2><p>Your product catalog, ready for the next order.</p></div>${link('Manage inventory →',url('inventory'))}</div><div class="store-products">${state.products.map((p,i)=>`<article class="store-product">${productPhoto(p.id)}<span class="product-number">0${i+1}</span><div><h3>${p.name}</h3><strong>${money(p.price)}</strong></div><footer><span>${p.stock} in stock</span>${btn('Adjust stock','stock',p.id,true)}</footer></article>`).join('')}</div><section class="store-orders"><header class="section-title"><h2>Latest orders</h2>${link('All orders →',url('orders'))}</header>${orders}</section></section>
 <aside class="store-summary"><section class="sales-receipt"><span class="eyebrow">STORE TOTALS / DEMO DATA</span>${icon('orders')}<h2>${money(revenue)}</h2><p>Order value, excluding cancellations</p><dl><div><dt>Orders</dt><dd>${state.orders.length}</dd></div><div><dt>Average order</dt><dd>${money(state.orders.length?revenue/state.orders.length:0)}</dd></div><div><dt>Awaiting fulfillment</dt><dd>${processing.length}</dd></div></dl>${link('View order book →',url('orders'))}</section><section class="fulfillment-note"><span class="icon-tile">${icon('inventory')}</span><h3>Ready to go?</h3><p>${processing.length} orders are waiting to be packed.</p>${processing.length?link('Prepare order #'+processing[0].id,url('orders',{id:processing[0].id}),true):link('Review all orders',url('orders'),true)}</section><section class="stock-list"><header class="section-title"><h3>Stock watch</h3><span>${low.length} items</span></header>${low.map(p=>`<div>${productPhoto(p.id,true)}<span><strong>${p.name}</strong><small>${p.stock} remaining</small></span>${btn('Restock','stock',p.id,true)}</div>`).join('')||'<p>All products are stocked.</p>'}</section></aside></div>`;
}
